class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: EF 9 uses "sync" semantics that require async for Cosmos.
        // However the raw SQL below must reference "Discriminator" (not "$type")
        // to match existing documents.
        var blogs = context.Blogs
            .FromSqlRaw("SELECT * FROM c WHERE c.Discriminator = 'Blog'")
            .ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

